        nx, ny = pos
        if 0 <= nx < width and 0 <= ny < height:
            if grid and grid[ny][nx] != 0:
                return False
            return True
        return False

    target_coords = None
    if mode == 'resource_collection' and resources:
        target_coords = min(resources, key=lambda r: abs(r[0] - x) + abs(r[1] - y))
    elif mode == 'pursuit_evasion' and opponents:
        target_coords = min(opponents, key=lambda o: abs(o[0] - x) + abs(o[1] - y))
    elif mode == 'territory_control' and territory_map:
        target_coords = min(territory_map, key=lambda t: abs(t[0] - x) + abs(t[1] - y))
    else:
        target_coords = None

    dx, dy = 0, 0
    if target_coords:
        tx, ty = target_coords
        delta_x = tx - x
        delta_y = ty - y
        # Decide axis priority
        if abs(delta_x) > abs(delta_y):
            dx = 1 if delta_x > 0 else -1 if delta_x < 0 else 0
        elif abs(delta_y) > 0:
            dy = 1 if delta_y > 0 else -1 if delta_y < 0 else 0
        # Validate move; if blocked, try alternatives
        if not is_valid((x + dx, y + dy)):
            for alt_dx, alt_dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                if is_valid((x + alt_dx, y + alt_dy)):
                    dx, dy = alt_dx, alt_dy
                    break
    else:
        # No target, pick a safe move
