            if is_valid((x + alt_dx, y + alt_dy)):
                dx, dy = alt_dx, alt_dy
                break

    # Clamp movement to -1, 0, 1
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]

